+        if (obj == null) {
+            return false;
+        }
+        if (obj.getClass() != getClass()) {
+            return false;
+        }
+        MigrateAction other = (MigrateAction) obj;
+        return Objects.equals(enabled, other.enabled);
+    }
+
+    @Override
+    public String toString() {
+        return Strings.toString(this);
+    }
+
