+                "data migration in each phase");
+        }
+    }
+
+    private static boolean definesAllocationRules(AllocateAction action) {
+        return action.getRequire().isEmpty() == false || action.getInclude().isEmpty() == false || action.getExclude().isEmpty() == false;
