+    private void or(final LongArray otherArr) {
+        long pos = otherArr.size();
+        bits = bigArrays.grow(bits, pos + 1);
+        final LongArray thisArr = this.bits;
+        while (--pos >= 0) {
+            thisArr.set(pos, thisArr.get(pos) | otherArr.get(pos));
+        }
+    }
