+        logger.lifecycle("Commit date of current: {}", timeOfCurrent);
+
+        String mergeCommits = execInCheckoutDir(
+            spec -> spec.commandLine(asList("git", "rev-list", defaultRefSpec, "--after", timeOfCurrent, "--merges"))
